import { createClient } from "@/lib/supabase/server";
import { getSupabaseEnv } from "@/lib/supabase/env";
import { jsonError, jsonOk } from "@/lib/http";
import { utcIsoDate } from "@/lib/tasks/dates";
import { logDatabaseError, taskWriteFailure } from "@/lib/tasks/db-errors";
import { fieldErrorMap, taskCreateSchema, taskListQuerySchema } from "@/lib/tasks/schema";
import { toTask, type TaskCounts, type TaskRow } from "@/lib/tasks/types";

async function requireSupabase() {
  if (!getSupabaseEnv()) {
    return {
      error: jsonError(500, "Server is missing Supabase configuration."),
    } as const;
  }

  const supabase = await createClient();
  const { data, error } = await supabase.auth.getClaims();
  if (error || !data?.claims.sub) {
    return { error: jsonError(401, "Authentication required.") } as const;
  }

  return { supabase, userId: data.claims.sub } as const;
}

export async function GET(request: Request) {
  const context = await requireSupabase();
  if ("error" in context) {
    return context.error;
  }

  const url = new URL(request.url);
  const parsed = taskListQuerySchema.safeParse({
    q: url.searchParams.get("q") ?? undefined,
    status: url.searchParams.get("status") ?? undefined,
    priority: url.searchParams.get("priority") ?? undefined,
    due: url.searchParams.get("due") ?? undefined,
    today: url.searchParams.get("today") ?? undefined,
  });

  if (!parsed.success) {
    return jsonError(400, "The filters are invalid.", { fieldErrors: fieldErrorMap(parsed.error) });
  }

  const today = parsed.data.today ?? utcIsoDate();
  const status = !parsed.data.status || parsed.data.status === "all" ? null : parsed.data.status;
  const priority =
    !parsed.data.priority || parsed.data.priority === "all" ? null : Number(parsed.data.priority);
  const due = !parsed.data.due || parsed.data.due === "all" ? null : parsed.data.due;

  const { data, error } = await context.supabase.rpc("list_my_tasks", {
    p_query: parsed.data.q || null,
    p_status: status,
    p_priority: priority,
    p_due: due,
    p_today: today,
  });

  if (error) {
    logDatabaseError("tasks.list", error);
    const missing = error.code === "PGRST202" || /could not find the function/i.test(error.message);
    return jsonError(
      500,
      missing
        ? "The database migration has not been applied."
        : "Tasks could not be loaded.",
    );
  }

  const rows = (data ?? []) as TaskRow[];
  const tasks = rows.map(toTask).sort(compareTasks);

  const { data: summaryRows, error: summaryError } = await context.supabase
    .from("tasks")
    .select("status, due_date")
    .is("deleted_at", null);

  if (summaryError) {
    logDatabaseError("tasks.counts", summaryError);
    return jsonError(500, "Tasks could not be loaded.");
  }

  const summary = summaryRows ?? [];
  const counts: TaskCounts = {
    total: summary.length,
    pending: summary.filter((row) => row.status === "pending").length,
    completed: summary.filter((row) => row.status === "completed").length,
    overdue: summary.filter(
      (row) => row.status === "pending" && String(row.due_date).slice(0, 10) < today,
    ).length,
    showing: tasks.length,
  };

  return jsonOk({ tasks, counts });
}

export async function POST(request: Request) {
  const context = await requireSupabase();
  if ("error" in context) {
    return context.error;
  }

  const body = await readJson(request);
  if (body === null) {
    return jsonError(400, "The request body must be JSON.");
  }

  const record = isRecord(body) ? { ...body, notes: typeof body.notes === "string" ? body.notes : "" } : body;
  const parsed = taskCreateSchema.safeParse(record);
  if (!parsed.success) {
    return jsonError(400, "The task could not be created.", {
      fieldErrors: fieldErrorMap(parsed.error),
    });
  }

  const { data, error } = await context.supabase
    .from("tasks")
    .insert({
      user_id: context.userId,
      title: parsed.data.title,
      notes: parsed.data.notes,
      due_date: parsed.data.dueDate,
      priority: parsed.data.priority,
      status: "pending",
    })
    .select("id, title, notes, due_date, priority, status, created_at, updated_at")
    .single();

  if (error) {
    logDatabaseError("tasks.create", error);
    const failure = taskWriteFailure(
      error,
      "An active task with this title and due date already exists.",
    );
    return jsonError(failure.status, failure.message);
  }

  return jsonOk({ task: toTask(data as TaskRow) }, 201);
}

function compareTasks(
  left: { dueDate: string; createdAt: string; id: string },
  right: { dueDate: string; createdAt: string; id: string },
): number {
  return (
    left.dueDate.localeCompare(right.dueDate) ||
    left.createdAt.localeCompare(right.createdAt) ||
    left.id.localeCompare(right.id)
  );
}

async function readJson(request: Request): Promise<unknown | null> {
  try {
    return await request.json();
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { createClient } from "@/lib/supabase/server";
import { getSupabaseEnv } from "@/lib/supabase/env";
import { jsonError, jsonOk } from "@/lib/http";
import { logDatabaseError, taskWriteFailure } from "@/lib/tasks/db-errors";
import { fieldErrorMap, taskPatchSchema } from "@/lib/tasks/schema";
import { toTask, type TaskRow } from "@/lib/tasks/types";

const TASK_COLUMNS = "id, title, notes, due_date, priority, status, created_at, updated_at";

async function requireSupabase() {
  if (!getSupabaseEnv()) {
    return { error: jsonError(500, "Server is missing Supabase configuration.") } as const;
  }

  const supabase = await createClient();
  const { data, error } = await supabase.auth.getClaims();
  if (error || !data?.claims.sub) {
    return { error: jsonError(401, "Authentication required.") } as const;
  }

  return { supabase } as const;
}

export async function PATCH(request: Request, context: { params: Promise<{ id: string }> }) {
  const auth = await requireSupabase();
  if ("error" in auth) {
    return auth.error;
  }

  const { id } = await context.params;
  if (!isUuid(id)) {
    return jsonError(404, "Task not found.");
  }

  const body = await readJson(request);
  if (!isRecord(body)) {
    return jsonError(400, "The request body must be JSON.");
  }

  const parsed = taskPatchSchema.safeParse(body);
  if (!parsed.success) {
    return jsonError(400, "The task could not be updated.", {
      fieldErrors: fieldErrorMap(parsed.error),
    });
  }

  const update: {
    title?: string;
    notes?: string | null;
    due_date?: string;
    priority?: number;
    status?: "pending" | "completed";
  } = {};

  if (parsed.data.title !== undefined) {
    update.title = parsed.data.title;
  }
  if (parsed.data.notes !== undefined) {
    update.notes = parsed.data.notes;
  }
  if (parsed.data.dueDate !== undefined) {
    update.due_date = parsed.data.dueDate;
  }
  if (parsed.data.priority !== undefined) {
    update.priority = parsed.data.priority;
  }
  if (parsed.data.status !== undefined) {
    update.status = parsed.data.status;
  }

  const { data, error } = await auth.supabase
    .from("tasks")
    .update(update)
    .eq("id", id)
    .is("deleted_at", null)
    .select(TASK_COLUMNS)
    .maybeSingle();

  if (error) {
    logDatabaseError("tasks.update", error);
    const failure = taskWriteFailure(
      error,
      "An active task with this title and due date already exists.",
    );
    return jsonError(failure.status, failure.message);
  }

  if (!data) {
    return jsonError(404, "Task not found.");
  }

  return jsonOk({ task: toTask(data as TaskRow) });
}

export async function DELETE(_request: Request, context: { params: Promise<{ id: string }> }) {
  const auth = await requireSupabase();
  if ("error" in auth) {
    return auth.error;
  }

  const { id } = await context.params;
  if (!isUuid(id)) {
    return jsonError(404, "Task not found.");
  }

  const { data, error } = await auth.supabase
    .from("tasks")
    .update({ deleted_at: new Date().toISOString() })
    .eq("id", id)
    .is("deleted_at", null)
    .select("id")
    .maybeSingle();

  if (error) {
    logDatabaseError("tasks.delete", error);
    return jsonError(500, "The task could not be deleted.");
  }

  if (!data) {
    return jsonError(404, "Task not found.");
  }

  return jsonOk({ deleted: true });
}

function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}

async function readJson(request: Request): Promise<unknown> {
  try {
    return await request.json();
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { buildRejectedCsv } from "@/lib/csv/rejected-csv";
import { CsvImportError, existingTaskKey, planCsvImport } from "@/lib/csv/plan-import";
import { jsonError, jsonOk } from "@/lib/http";
import { importFailure, logDatabaseError } from "@/lib/tasks/db-errors";
import { MAX_CSV_BYTES } from "@/lib/tasks/limits";
import { getSupabaseEnv } from "@/lib/supabase/env";
import { createClient } from "@/lib/supabase/server";
import { z } from "zod";

const importResultSchema = z.object({
  inserted_count: z.number().int().nonnegative(),
  inserted_ids: z.array(z.string()),
});

export async function POST(request: Request) {
  if (!getSupabaseEnv()) {
    return jsonError(500, "Server is missing Supabase configuration.");
  }

  const supabase = await createClient();
  const { data: claimsData, error: claimsError } = await supabase.auth.getClaims();
  if (claimsError || !claimsData?.claims.sub) {
    return jsonError(401, "Authentication required.");
  }

  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return jsonError(400, "Upload a CSV file.");
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return jsonError(400, "Choose a CSV file to import.");
  }

  const filename = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  const typeAllowed =
    type === "" ||
    type === "text/csv" ||
    type === "application/csv" ||
    type === "application/vnd.ms-excel" ||
    type === "text/plain";

  if (!filename.endsWith(".csv") || !typeAllowed) {
    return jsonError(415, "Upload a .csv file.");
  }

  if (file.size > MAX_CSV_BYTES) {
    return jsonError(413, `The CSV file exceeds the ${MAX_CSV_BYTES} byte limit.`);
  }

  const content = await file.text();

  let plan;
  try {
    const { data: existing, error: existingError } = await supabase
      .from("tasks")
      .select("title, due_date")
      .is("deleted_at", null);

    if (existingError) {
      logDatabaseError("tasks.import.existing", existingError);
      return jsonError(500, "Existing tasks could not be checked. Nothing was imported.");
    }

    const keys = new Set<string>();
    for (const row of existing ?? []) {
      keys.add(existingTaskKey(String(row.title), String(row.due_date)));
    }

    plan = planCsvImport(content, keys);
  } catch (error) {
    if (error instanceof CsvImportError) {
      return jsonError(error.status, error.message);
    }
    console.error("[tasks.import] parse failed");
    return jsonError(400, "The CSV file could not be imported.");
  }

  const rejectedCsv = buildRejectedCsv(plan.rejected);

  if (plan.accepted.length === 0) {
    return jsonOk({
      importedCount: 0,
      rejectedCount: plan.rejected.length,
      insertedIds: [],
      rejected: plan.rejected,
      rejectedCsv,
      message:
        plan.dataRowCount === 0
          ? "No data rows were found."
          : "No rows were imported. Review the rejected rows.",
    });
  }

  const { data, error } = await supabase.rpc("import_tasks", {
    candidates: plan.accepted.map((row) => ({
      title: row.title,
      due_date: row.dueDate,
      priority: row.priority,
      notes: row.notes,
    })),
  });

  if (error) {
    logDatabaseError("tasks.import", error);
    const failure = importFailure(error);
    return jsonError(failure.status, failure.message, {
      importedCount: 0,
      rejectedCount: plan.rejected.length,
      insertedIds: [],
      rejected: plan.rejected,
      rejectedCsv,
    });
  }

  const parsed = importResultSchema.safeParse(data);
  if (!parsed.success || parsed.data.inserted_count !== plan.accepted.length) {
    console.error("[tasks.import] unexpected import result");
    return jsonError(500, "The import result did not match the accepted rows. Refresh the task list before trying again.", {
      importedCount: 0,
      rejectedCount: plan.rejected.length,
      insertedIds: [],
      rejected: plan.rejected,
      rejectedCsv,
    });
  }

  return jsonOk({
    importedCount: parsed.data.inserted_count,
    rejectedCount: plan.rejected.length,
    insertedIds: parsed.data.inserted_ids,
    rejected: plan.rejected,
    rejectedCsv,
    message: `${parsed.data.inserted_count} task${parsed.data.inserted_count === 1 ? "" : "s"} imported. ${plan.rejected.length} row${plan.rejected.length === 1 ? "" : "s"} rejected.`,
  });
}

import { NextResponse } from "next/server";

import { createClient } from "@/lib/supabase/server";
import { getSupabaseEnv } from "@/lib/supabase/env";

export async function GET(request: Request) {
  const url = new URL(request.url);
  const code = url.searchParams.get("code");
  const next = url.searchParams.get("next") ?? "/tasks";
  const destination = new URL(next.startsWith("/") ? next : "/tasks", url.origin);

  if (!getSupabaseEnv()) {
    destination.pathname = "/login";
    destination.searchParams.set("error", "configuration");
    return NextResponse.redirect(destination);
  }

  if (code) {
    const supabase = await createClient();
    const { error } = await supabase.auth.exchangeCodeForSession(code);
    if (error) {
      destination.pathname = "/login";
      destination.searchParams.set("error", "confirmation");
      return NextResponse.redirect(destination);
    }
  }

  return NextResponse.redirect(destination);
}

