  input: T,
): T {
  const next = { ...input };
  if (typeof next.title === "string") {
    next.title = trimTaskText(next.title);
  }
  if (typeof next.notes === "string") {
    const notes = trimTaskText(next.notes);
    next.notes = notes.length === 0 ? null : notes;
  }
  if (typeof next.dueDate === "string") {
    next.dueDate = next.dueDate.trim();
  }
  return next;
}

