const fieldClass =
  "mt-1 w-full rounded-md border border-stone-300 bg-white px-3 py-2 text-sm outline-none focus:border-teal-800 focus:ring-2 focus:ring-teal-800/20";

const primaryClass =
  "rounded-md bg-teal-800 px-4 py-2 text-sm font-medium text-white hover:bg-teal-900 disabled:cursor-not-allowed disabled:opacity-60";

const secondaryClass =
  "rounded-md border border-stone-300 bg-white px-4 py-2 text-sm font-medium hover:bg-stone-50 disabled:opacity-60";

"use client";

import { useState } from "react";

import type { RejectedCsvRow } from "@/lib/csv/plan-import";

type ImportResult = {
  importedCount: number;
  rejectedCount: number;
  rejected: RejectedCsvRow[];
  rejectedCsv: string;
  message?: string;
  error?: string;
};

export function ImportPanel({ onImported }: { onImported: () => Promise<void> }) {
  const [file, setFile] = useState<File | null>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<ImportResult | null>(null);

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!file || pending) {
      return;
    }

    setPending(true);
    setError(null);
    const body = new FormData();
    body.set("file", file);

    try {
      const response = await fetch("/api/tasks/import", { method: "POST", body });
      const payload = (await response.json()) as ImportResult & { error?: string };
      if (!response.ok) {
        setError(payload.error ?? "The CSV could not be imported.");
        setResult(payload.rejected ? payload : null);
        return;
      }
      setResult(payload);
      setFile(null);
      await onImported();
    } catch {
      setError("The server could not be reached.");
    } finally {
      setPending(false);
    }
  }

  function downloadRejected() {
    if (!result?.rejectedCsv) {
      return;
    }
    const blob = new Blob([result.rejectedCsv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "rejected-tasks.csv";
    link.click();
    URL.revokeObjectURL(url);
  }

  return (
    <section className="rounded-xl border border-stone-200 bg-white p-4 shadow-sm">
      <h2 className="text-lg font-semibold">Import CSV</h2>
      <p className="mt-1 text-sm text-stone-600">
        Headers must be <span className="font-mono text-xs">title,due_date,priority,notes</span>.
        Limit: 1 MB and 1,000 data rows.
      </p>
      <p className="mt-2 text-sm">
        <a className="font-medium text-teal-800 underline" href="/samples/import-edge-cases.csv">
          Download the edge-case sample
        </a>
      </p>
      <form className="mt-4 space-y-3" onSubmit={onSubmit}>
        <label className="block text-sm font-medium" htmlFor="csv-file">
          CSV file
          <input
            id="csv-file"
            type="file"
            accept=".csv,text/csv"
            className="mt-1 block w-full text-sm"
            onChange={(event) => {
              setFile(event.target.files?.[0] ?? null);
              setResult(null);
              setError(null);
            }}
          />
        </label>
        <button
          type="submit"
          className="rounded-md bg-teal-800 px-4 py-2 text-sm font-medium text-white hover:bg-teal-900 disabled:cursor-not-allowed disabled:opacity-60"
          disabled={pending || !file}
        >
          {pending ? "Importing…" : "Import"}
        </button>
      </form>
      {pending ? (
        <p className="mt-3 text-sm text-stone-600" role="status">
          Parsing and saving the file. Valid rows are saved together.
        </p>
      ) : null}
      {error ? (
        <p className="mt-3 text-sm text-rose-800" role="alert">
          {error}
        </p>
      ) : null}
      {result && !error ? (
        <div className="mt-4" role="status" aria-live="polite">
          <p className="text-sm font-medium text-teal-900">{result.message}</p>
          <p className="mt-1 text-sm text-stone-700">
            Imported {result.importedCount}. Rejected {result.rejectedCount}.
          </p>
        </div>
      ) : null}
      {result && result.rejected.length > 0 ? (
        <div className="mt-4">
          <div className="flex items-center justify-between gap-3">
            <h3 className="text-sm font-semibold">Rejected rows</h3>
            <button
              type="button"
              className="rounded-md border border-stone-300 px-3 py-1 text-sm hover:bg-stone-50"
              onClick={downloadRejected}
            >
              Download rejected CSV
            </button>
          </div>
          <div className="mt-2 overflow-x-auto">
            <table className="w-full min-w-[28rem] text-left text-sm">
              <caption className="sr-only">CSV rows that were not imported</caption>
              <thead className="text-stone-500">
                <tr>
                  <th className="py-1 pr-3 font-medium">Row</th>
                  <th className="py-1 pr-3 font-medium">Title</th>
                  <th className="py-1 font-medium">Reason</th>
                </tr>
              </thead>
              <tbody>
                {result.rejected.map((row) => (
                  <tr key={`${row.rowNumber}-${row.reason}`} className="border-t border-stone-100">
                    <td className="py-2 pr-3">{row.rowNumber}</td>
                    <td className="max-w-40 truncate py-2 pr-3">{row.title || "—"}</td>
                    <td className="py-2">{row.reason}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : null}
    </section>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";

import { ImportPanel } from "@/components/import-panel";
import { TaskForm } from "@/components/task-form";
import { createClient } from "@/lib/supabase/client";
import { localIsoDate } from "@/lib/tasks/dates";
import type { TaskCreateInput } from "@/lib/tasks/schema";
import type { Task, TaskCounts } from "@/lib/tasks/types";

type Filters = {
  q: string;
  status: "all" | "pending" | "completed";
  priority: "all" | "1" | "2" | "3" | "4" | "5";
  due: "all" | "overdue" | "today" | "upcoming";
};

const EMPTY_FILTERS: Filters = { q: "", status: "all", priority: "all", due: "all" };

export function TaskDashboard({ email }: { email: string }) {
  const router = useRouter();
  const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [counts, setCounts] = useState<TaskCounts | null>(null);
  const [loading, setLoading] = useState(true);
  const [listError, setListError] = useState<string | null>(null);
  const [createError, setCreateError] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editError, setEditError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [pendingDelete, setPendingDelete] = useState<Task | null>(null);

  const loadTasks = useCallback(async () => {
    const params = new URLSearchParams();
    if (filters.q.trim()) params.set("q", filters.q.trim());
    if (filters.status !== "all") params.set("status", filters.status);
    if (filters.priority !== "all") params.set("priority", filters.priority);
    if (filters.due !== "all") params.set("due", filters.due);
    params.set("today", localIsoDate());

    const response = await fetch(`/api/tasks?${params.toString()}`, { cache: "no-store" });
    const body = (await response.json()) as { tasks?: Task[]; counts?: TaskCounts; error?: string };
    if (!response.ok) {
      throw new Error(body.error ?? "Tasks could not be loaded.");
    }
    setTasks(body.tasks ?? []);
    setCounts(body.counts ?? null);
  }, [filters]);

  useEffect(() => {
    let cancelled = false;
    setListError(null);
    loadTasks()
      .catch((error: unknown) => {
        if (!cancelled) {
          setListError(error instanceof Error ? error.message : "Tasks could not be loaded.");
        }
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [loadTasks]);

  async function refresh() {
    setListError(null);
    try {
      await loadTasks();
    } catch (error: unknown) {
      setListError(error instanceof Error ? error.message : "Tasks could not be loaded.");
    }
  }

  async function createTask(values: TaskCreateInput) {
    setCreating(true);
    setCreateError(null);
    try {
      const response = await fetch("/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(values),
      });
      const body = (await response.json()) as { error?: string };
      if (!response.ok) {
        setCreateError(body.error ?? "The task could not be created.");
        return;
      }
      await refresh();
    } catch {
      setCreateError("The server could not be reached.");
    } finally {
      setCreating(false);
    }
  }

  async function updateTask(id: string, values: Partial<TaskCreateInput> & { status?: Task["status"] }) {
    setBusyId(id);
    setEditError(null);
    try {
      const response = await fetch(`/api/tasks/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(values),
      });
      const body = (await response.json()) as { error?: string };
      if (!response.ok) {
        setEditError(body.error ?? "The task could not be updated.");
        return;
      }
      setEditingId(null);
      await refresh();
    } catch {
      setEditError("The server could not be reached.");
    } finally {
      setBusyId(null);
    }
  }

  async function confirmDelete() {
    if (!pendingDelete) return;
    const id = pendingDelete.id;
    setBusyId(id);
    try {
      const response = await fetch(`/api/tasks/${id}`, { method: "DELETE" });
      const body = (await response.json()) as { error?: string };
      if (!response.ok) {
        setListError(body.error ?? "The task could not be deleted.");
        return;
      }
      setPendingDelete(null);
      await refresh();
    } catch {
      setListError("The server could not be reached.");
    } finally {
      setBusyId(null);
    }
  }

  async function signOut() {
    const supabase = createClient();
    await supabase.auth.signOut();
    router.push("/login");
    router.refresh();
  }

  const filtersActive =
    filters.q !== "" || filters.status !== "all" || filters.priority !== "all" || filters.due !== "all";
  const today = localIsoDate();

  return (
    <div className="mx-auto min-h-full max-w-6xl px-4 py-6 sm:px-6">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-sm font-medium text-teal-800">Task List</p>
          <h1 className="text-2xl font-semibold tracking-tight">Your tasks</h1>
        </div>
        <div className="flex items-center gap-3 text-sm">
          <span className="text-stone-600">{email}</span>
          <button
            type="button"
            className="rounded-md border border-stone-300 bg-white px-3 py-1.5 hover:bg-stone-50"
            onClick={signOut}
          >
            Sign out
          </button>
        </div>
      </header>

      <section className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-5" aria-label="Task counts">
        <Count label="Active" value={counts?.total} />
        <Count label="Pending" value={counts?.pending} />
        <Count label="Completed" value={counts?.completed} />
        <Count label="Overdue" value={counts?.overdue} />
        <Count label="Showing" value={counts?.showing} />
